(async()=>{const calls=[],box=document.createElement('div');document.body.appendChild(box);class AdjacentProbe extends HTMLElement{connectedCallback(){calls.push('connect:'+this.id)}disconnectedCallback(){calls.push('disconnect:'+this.id)}}customElements.define('adjacent-probe',AdjacentProbe);box.innerHTML='<i>left</i><adjacent-probe id="old"></adjacent-probe><b>right</b>';calls.length=0;const old=box.querySelector('adjacent-probe'),records=[],observer=new MutationObserver(items=>{for(const r of items)records.push({target:r.target===box?'box':'old',added:Array.from(r.addedNodes,n=>n.id||n.nodeName),removed:Array.from(r.removedNodes,n=>n.id||n.nodeName),previous:r.previousSibling?.id||r.previousSibling?.nodeName||null,next:r.nextSibling?.id||r.nextSibling?.nodeName||null})});observer.observe(box,{childList:true,subtree:true});old.insertAdjacentHTML('beforebegin','<adjacent-probe id="before"></adjacent-probe>');old.insertAdjacentHTML('beforeend','<adjacent-probe id="inside"></adjacent-probe>');old.outerHTML='<adjacent-probe id="replacement"></adjacent-probe>';old.appendChild(document.createElement('em'));const synchronous=calls.slice();await Promise.resolve();observer.disconnect();return {synchronous,records,oldDetached:old.parentNode===null,oldChildren:old.childNodes.length}})()